<?php $pageTitle='Import Products';$subtitle='Add products in bulk from Excel, PDF documents or product photos.';$active='Import Products';require __DIR__.'/_layout.php';?><div class="grid two"><section class="card"><div class="section-head"><h2>Scan / import</h2></div><div class="drop"><input id="file" type="file" accept=".xlsx,.xls,.csv,.pdf,image/*" class="input"><p style="color:var(--muted);margin:12px 0 0">Excel preserves columns. PDF and image imports use browser-side extraction/OCR and should be reviewed before saving.</p></div><div id="progress" style="display:none;margin-top:15px"><div class="progress"><i id="bar" style="width:10%"></i></div><p id="progressText" style="color:var(--muted)"></p></div></section><section class="card"><h2>Supported product fields</h2><p style="color:var(--muted);line-height:1.7">Use headers such as Product Name, Brand, Category, Model Name, Product ID / P-ID, Barcode, CAT No., MRP, Selling Price, Stock, Rating, Description, Key Features, Specifications, Voltage, Manufactured On, Maximum Suction, Net Weight, Net Contents and Product Image.</p><a class="btn" href="data:text/csv;charset=utf-8,Product%20Name%2CBrand%2CCategory%2CMRP%2CSelling%20Price%2CStock%2CProduct%20ID%20%2F%20P-ID%2CBarcode%2CDescription%0ASolar%20Panel%20550W%2CSolarMax%2CSolar%20Panel%2C22000%2C18999%2C25%2CSW-SP-550%2C123456%2CHigh-efficiency%20panel" download="swarnim-product-template.csv">Download CSV Template</a></section></div><section class="card" style="margin-top:18px"><div class="section-head"><h2>Review imported products</h2><div class="actions"><span id="count" class="pill blue">0 rows</span><button class="btn primary" id="save" disabled>Save Products</button></div></div><div class="table-wrap"><table id="preview"><thead><tr><th>Product</th><th>Brand</th><th>Category</th><th>Price</th><th>Stock</th><th>PID</th><th>Image</th></tr></thead><tbody><tr><td colspan="7" class="empty">Choose a file to preview.</td></tr></tbody></table></div><pre id="errors" style="white-space:pre-wrap;color:#ff9aaa"></pre></section>
<script src="https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.min.mjs" type="module"></script><script src="https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js"></script><script>let rows=[];const fileEl=document.querySelector('#file'),save=document.querySelector('#save'),bar=document.querySelector('#bar'),progress=document.querySelector('#progress'),pt=document.querySelector('#progressText');const aliases={'Product Name':'name','Name':'name','Brand':'brand','Category':'category','Model Name':'model_name','Product ID / P-ID':'product_pid','P-ID':'product_pid','Barcode':'barcode','Item':'item','CAT No.':'cat_no','Product Size':'product_size','Color / Finish':'color_finish','Net Quantity':'net_quantity','MRP':'mrp','Selling Price':'selling_price','Old Price':'old_price','Discount %':'discount_percent','You Save':'you_save','Stock':'stock','Rating':'rating','Reviews':'reviews','Badge':'badge','Tagline':'tagline','Description':'description','Key Features':'key_features','Specifications':'specifications','Voltage':'voltage','Manufactured On':'manufactured_on','Maximum Suction':'maximum_suction','Net Weight':'net_weight','Net Contents':'net_contents','Product Image':'image_url','SKU':'sku'};function norm(k){k=String(k||'').trim();return aliases[k]||k.toLowerCase().replace(/[^a-z0-9]+(.)/g,(_,c)=>c?c.toUpperCase():'').replace(/[^a-zA-Z0-9]/g,'')||k}function mapRow(r){const o={};for(const [k,v] of Object.entries(r)){const n=aliases[k]||norm(k);o[n]=v}return o}function show(){document.querySelector('#count').textContent=rows.length+' rows';save.disabled=!rows.length;const tb=document.querySelector('#preview tbody');tb.innerHTML=rows.slice(0,100).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.brand)}</td><td>${esc(r.category)}</td><td>₹${esc(r.selling_price||r.price||'0')}</td><td>${esc(r.stock||'0')}</td><td>${esc(r.product_pid)}</td><td>${r.image_url?'<span class="pill green">Available</span>':'—'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No rows detected.</td></tr>'}function esc(v){return String(v??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}function setProgress(t,p){progress.style.display='block';pt.textContent=t;bar.style.width=p+'%'}fileEl.addEventListener('change',async()=>{const f=fileEl.files[0];if(!f)return;rows=[];setProgress('Reading '+f.name,10);try{if(/\.(xlsx|xls|csv)$/i.test(f.name)){const data=await f.arrayBuffer();const wb=XLSX.read(data,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(ws,{defval:''}).map(mapRow)}else if(f.type==='application/pdf'||/\.pdf$/i.test(f.name)){const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:await f.arrayBuffer()}).promise;let text='';for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const c=await page.getTextContent();text+=c.items.map(x=>x.str).join(' ')+'\n'}rows=[parseText(text)];}else if(f.type.startsWith('image/')){const out=await Tesseract.recognize(f,'eng',{logger:m=>{if(m.progress)setProgress('OCR: '+m.status,10+m.progress*80)}});rows=[parseText(out.data.text)]}else throw new Error('Unsupported file type');show();setProgress('Review complete',100)}catch(e){document.querySelector('#errors').textContent=e.message||String(e);setProgress('Could not read file',100)}});function parseText(t){const o={};const labels=Object.keys(aliases).sort((a,b)=>b.length-a.length);for(const label of labels){const re=new RegExp(label.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\s*[:\-]?\\s*([^\\n]+)','i');const m=t.match(re);if(m)o[aliases[label]]=m[1].trim()}if(!o.name){const m=t.match(/(?:Product Name|Name)\s*[:\-]?\s*([^\n]+)/i);if(m)o.name=m[1].trim()}return o}save.addEventListener('click',async()=>{if(!rows.length)return;save.disabled=true;setProgress('Saving products...',20);const fd=new FormData();fd.append('action','bulk-import');fd.append('rows',JSON.stringify(rows));const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);document.querySelector('#errors').textContent=(j.data?.errors||[]).join('\n');setProgress(j.message,100);save.disabled=false;if(j.ok&&j.data?.added)setTimeout(()=>location.href='products.php',900)})</script><?php require __DIR__.'/_foot.php'; ?>
